import re,os,collections
D='<repo>/.tmp/lc3/'
def res(p):
    if not os.path.exists(p): return None
    t=open(p).read()
    st=re.search(r'States analysed: (\d+)',t); dp=re.search(r'Breadth-first levels: (\d+)',t)
    return (int(st.group(1)) if st else None),(int(dp.group(1)) if dp else None)
m=collections.defaultdict(set)
for l in open(D+'rows6.txt'):
    n=l.split()[0]
    o=res(D+'r6_prev6/%s.out'%n); nw=res(D+'r6/%s.out'%n)
    if o and nw and o!=nw: m[o].add((n,nw))
for k,v in sorted(m.items()):
    print(k, sorted(set(x[1] for x in v)), [x[0] for x in v][:4])
EOF
